  --text-secondary: oklch(75% 0.01 255);
  --text-muted: oklch(58% 0.01 255);
  --text-dim: oklch(45% 0.01 255);

  /* Accents */
  --accent-teal: oklch(68% 0.14 225);
  --accent-teal-glow: oklch(68% 0.14 225 / 0.2);
  --accent-blue: oklch(52% 0.17 252);
  --accent-blue-glow: oklch(52% 0.17 252 / 0.2);
  --accent-green: oklch(72% 0.18 145);
  --accent-green-glow: oklch(72% 0.18 145 / 0.15);
  --accent-amber: oklch(75% 0.15 85);

  /* Borders */
  --border-default: oklch(32% 0.015 255);
  --border-light: oklch(24% 0.015 255);
  --border-glow: oklch(68% 0.14 225 / 0.25);

  /* Typography */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;

  /* Spacing Scale (8px base) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;
  --space-10: 128px;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.35);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.45);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.55);
  --shadow-glow-teal: 0 0 30px oklch(68% 0.14 225 / 0.12);
  --shadow-glow-blue: 0 0 30px oklch(52% 0.17 252 / 0.1);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --transition-fast: 150ms var(--ease-out);
  --transition-base: 250ms var(--ease-out);
  --transition-slow: 400ms var(--ease-out);

  /* Layout */
  --max-width: 1200px;
  --max-width-narrow: 900px;
  --header-height: 72px;
