/* ============================================================
   WellStream Platform — Shared Stylesheet
   Design: Professional, modern, dark | Energy Industry SaaS
   ============================================================ */

/* --- Design Tokens --- */
:root {
  /* Backgrounds */
  --bg-deep: oklch(12% 0.015 255);
  --bg-primary: oklch(15% 0.02 255);
  --bg-secondary: oklch(19% 0.025 255);
  --bg-card: oklch(22% 0.025 255);
  --bg-elevated: oklch(26% 0.025 255);
  --bg-hover: oklch(28% 0.025 255);

  /* Text */
  --text-primary: oklch(95% 0.005 255);
  --text-secondary: oklch(75% 0.01 255);
  --text-muted: oklch(58% 0.01 255);
  --text-dim: oklch(45% 0.01 255);

  /* Accents */
  --accent-teal: oklch(68% 0.14 225);
  --accent-teal-glow: oklch(68% 0.14 225 / 0.2);
  --accent-blue: oklch(52% 0.17 252);
  --accent-blue-glow: oklch(52% 0.17 252 / 0.2);
  --accent-green: oklch(72% 0.18 145);
  --accent-green-glow: oklch(72% 0.18 145 / 0.15);
  --accent-amber: oklch(75% 0.15 85);

  /* Borders */
  --border-default: oklch(32% 0.015 255);
  --border-light: oklch(24% 0.015 255);
  --border-glow: oklch(68% 0.14 225 / 0.25);

  /* Typography */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;

  /* Spacing Scale (8px base) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;
  --space-10: 128px;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.35);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.45);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.55);
  --shadow-glow-teal: 0 0 30px oklch(68% 0.14 225 / 0.12);
  --shadow-glow-blue: 0 0 30px oklch(52% 0.17 252 / 0.1);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --transition-fast: 150ms var(--ease-out);
  --transition-base: 250ms var(--ease-out);
  --transition-slow: 400ms var(--ease-out);

  /* Layout */
  --max-width: 1200px;
  --max-width-narrow: 900px;
  --header-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-secondary);
  background: var(--bg-deep);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

body.menu-open { overflow: hidden; }

img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font: inherit; border: none; background: none; color: inherit; }
input, select, textarea { font: inherit; color: inherit; }

/* Focus ring */
:focus-visible {
  outline: 2px solid var(--accent-teal);
  outline-offset: 2px;
}

/* Selection */
::selection {
  background: oklch(68% 0.14 225 / 0.3);
  color: var(--text-primary);
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  color: var(--text-primary);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.125rem; }

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-teal);
  margin-bottom: var(--space-3);
}

.section-title { margin-bottom: var(--space-3); }
.section-description {
  font-size: 1.125rem;
  color: var(--text-muted);
  max-width: 680px;
  margin-bottom: var(--space-6);
}

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.container-narrow {
  max-width: var(--max-width-narrow);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.section {
  padding: var(--space-8) 0;
  position: relative;
}

.section-dark { background: var(--bg-primary); }
.section-darker { background: var(--bg-deep); }

.section-header {
  text-align: center;
  margin-bottom: var(--space-6);
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--header-height);
  background: oklch(12% 0.015 255 / 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-light);
  transition: background var(--transition-base);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.01em;
  flex-shrink: 0;
}

.nav-logo-icon {
  width: 32px;
  height: 32px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.nav-link {
  padding: var(--space-2) var(--space-3);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: color var(--transition-fast), background var(--transition-fast);
  white-space: nowrap;
}

.nav-link:hover { color: var(--text-primary); background: var(--bg-hover); }

/* Dropdown */
.nav-dropdown {
  position: relative;
}

.nav-dropdown-toggle {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-2) var(--space-3);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: color var(--transition-fast), background var(--transition-fast);
}

.nav-dropdown-toggle:hover { color: var(--text-primary); background: var(--bg-hover); }

.nav-dropdown-toggle .chevron {
  width: 14px;
  height: 14px;
  transition: transform var(--transition-fast);
}

.nav-dropdown.open .nav-dropdown-toggle .chevron { transform: rotate(180deg); }
.nav-dropdown.open .nav-dropdown-toggle { color: var(--accent-teal); background: var(--bg-hover); }

.nav-dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  min-width: 220px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: var(--space-2);
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-fast), transform var(--transition-fast), visibility var(--transition-fast);
}

.nav-dropdown.open .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.nav-dropdown-menu a {
  display: block;
  padding: var(--space-2) var(--space-3);
  font-size: 0.875rem;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.nav-dropdown-menu a:hover { color: var(--text-primary); background: var(--bg-hover); }

/* Nav CTA Button */
.nav-cta {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--accent-teal);
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
  box-shadow: 0 0 20px var(--accent-teal-glow);
}

.nav-cta:hover {
  background: oklch(73% 0.14 225);
  box-shadow: 0 0 30px var(--accent-teal-glow);
  transform: translateY(-1px);
}

/* Hamburger */
.nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  z-index: 1001;
}

.nav-hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--text-primary);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.nav-hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.nav-hamburger.active span:nth-child(2) { opacity: 0; }
.nav-hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* Mobile nav */
.nav-mobile {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 999;
  background: var(--bg-deep);
  padding: calc(var(--header-height) + var(--space-4)) var(--space-4) var(--space-4);
  overflow-y: auto;
}

.nav-mobile.active { display: flex; flex-direction: column; gap: var(--space-1); }

.nav-mobile a,
.nav-mobile .nav-mobile-section-title {
  display: block;
  padding: var(--space-3);
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.nav-mobile a:hover { color: var(--text-primary); background: var(--bg-hover); }

.nav-mobile-section-title {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  padding-top: var(--space-4);
}

.nav-mobile .nav-cta {
  margin-top: var(--space-4);
  text-align: center;
  justify-content: center;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: 12px 28px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  line-height: 1.4;
}

.btn-primary {
  background: var(--accent-teal);
  color: var(--bg-deep);
  box-shadow: 0 0 24px var(--accent-teal-glow);
}

.btn-primary:hover {
  background: oklch(73% 0.14 225);
  box-shadow: 0 0 36px var(--accent-teal-glow);
  transform: translateY(-2px);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-default);
}

.btn-secondary:hover {
  border-color: var(--accent-teal);
  color: var(--accent-teal);
}

.btn-lg {
  padding: 16px 36px;
  font-size: 1.0625rem;
}

.btn-sm {
  padding: 8px 18px;
  font-size: 0.8125rem;
}

.btn-group {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
}

/* --- Hero --- */
.hero {
  padding: calc(var(--header-height) + var(--space-8)) 0 var(--space-8);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, var(--accent-teal-glow), transparent 70%);
  pointer-events: none;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -200px;
  left: -100px;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, var(--accent-blue-glow), transparent 70%);
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
}

.hero h1 {
  max-width: 800px;
  margin-bottom: var(--space-4);
}

.hero .hero-subtitle {
  font-size: 1.1875rem;
  color: var(--text-muted);
  max-width: 620px;
  margin-bottom: var(--space-5);
  line-height: 1.7;
}

/* Hero with diagram side-by-side */
.hero-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-7);
  align-items: center;
}

/* --- Cards --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  transition: all var(--transition-base);
}

.card:hover {
  border-color: var(--border-default);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-lg);
  background: oklch(68% 0.14 225 / 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-3);
  color: var(--accent-teal);
}

.card-icon svg {
  width: 24px;
  height: 24px;
}

.card h3, .card h4 {
  margin-bottom: var(--space-2);
}

.card p {
  font-size: 0.9375rem;
  color: var(--text-muted);
  line-height: 1.65;
}

/* Card grid layouts */
.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.card-grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.card-grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
}

/* --- Tabs --- */
.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  margin-bottom: var(--space-5);
  border-bottom: 1px solid var(--border-light);
  padding-bottom: 0;
}

.tabs-center { justify-content: center; }

.tab-btn {
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  border-radius: var(--radius-md) var(--radius-md) 0 0;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  margin-bottom: -1px;
}

.tab-btn:hover { color: var(--text-secondary); }

.tab-btn.active {
  color: var(--accent-teal);
  border-bottom-color: var(--accent-teal);
  background: oklch(68% 0.14 225 / 0.06);
}

.tab-panel { display: none; }
.tab-panel.active { display: block; animation: fadeSlideIn 0.3s var(--ease-out); }

/* Industry tabs variant */
.tabs-pills {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-5);
  border-bottom: none;
}

.tab-pill {
  padding: 8px 18px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-muted);
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.tab-pill:hover { color: var(--text-secondary); border-color: var(--border-default); }

.tab-pill.active {
  color: var(--accent-teal);
  background: oklch(68% 0.14 225 / 0.1);
  border-color: oklch(68% 0.14 225 / 0.3);
}

/* --- Accordion --- */
.accordion { display: flex; flex-direction: column; gap: var(--space-2); }

.accordion-item {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition-fast);
}

.accordion-item.active { border-color: var(--border-default); }

.accordion-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-4) var(--space-5);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text-primary);
  text-align: left;
  transition: color var(--transition-fast);
}

.accordion-trigger:hover { color: var(--accent-teal); }

.accordion-trigger .accordion-icon {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-full);
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-base);
  color: var(--text-muted);
}

.accordion-item.active .accordion-icon {
  background: oklch(68% 0.14 225 / 0.15);
  color: var(--accent-teal);
  transform: rotate(45deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s var(--ease-out);
}

.accordion-content-inner {
  padding: 0 var(--space-5) var(--space-5);
  color: var(--text-muted);
  line-height: 1.7;
}

/* --- Stats Circles --- */
.stats-row {
  display: flex;
  justify-content: center;
  gap: var(--space-7);
  flex-wrap: wrap;
}

.stat-circle {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.stat-circle-outer {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  border: 4px solid var(--border-default);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-3);
  position: relative;
  transition: border-color var(--transition-base);
}

.stat-circle-outer::before {
  content: '';
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 4px solid transparent;
  border-top-color: var(--accent-teal);
  border-right-color: var(--accent-teal);
  animation: statSpin 3s linear infinite;
}

.stat-circle:hover .stat-circle-outer {
  border-color: var(--accent-teal);
}

.stat-value {
  font-size: 2rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.stat-circle .stat-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  max-width: 160px;
  line-height: 1.4;
}

/* --- Timeline --- */
.timeline { position: relative; padding-left: var(--space-5); }

.timeline::before {
  content: '';
  position: absolute;
  left: 16px;
  top: 8px;
  bottom: 8px;
  width: 2px;
  background: var(--border-default);
}

.timeline-item {
  position: relative;
  padding-left: var(--space-5);
  padding-bottom: var(--space-5);
}

.timeline-item:last-child { padding-bottom: 0; }

.timeline-dot {
  position: absolute;
  left: -21px;
  top: 8px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--accent-teal);
  box-shadow: 0 0 12px var(--accent-teal-glow);
}

.timeline-duration {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--accent-teal);
  margin-bottom: var(--space-1);
}

.timeline-desc {
  font-size: 0.9375rem;
  color: var(--text-muted);
  margin-bottom: var(--space-3);
}

.progress-bar {
  height: 6px;
  background: var(--bg-elevated);
  border-radius: var(--radius-full);
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  border-radius: var(--radius-full);
  background: linear-gradient(90deg, var(--accent-teal), var(--accent-blue));
  transition: width 1s var(--ease-out);
}

.progress-25 { width: 25%; }
.progress-50 { width: 50%; }
.progress-100 { width: 100%; }

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s var(--ease-in-out);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 var(--space-1);
}

.testimonial-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.125rem;
  color: var(--text-primary);
  line-height: 1.7;
  font-style: italic;
  margin-bottom: var(--space-4);
}

.testimonial-quote::before { content: '"'; }
.testimonial-quote::after { content: '"'; }

.testimonial-author {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--accent-teal);
}

.testimonial-role {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: var(--space-1);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  margin-top: var(--space-5);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-default);
  transition: all var(--transition-fast);
}

.carousel-dot.active { background: var(--accent-teal); width: 28px; border-radius: var(--radius-full); }
.carousel-dot:hover { background: var(--text-muted); }

/* --- Forms --- */
.form-section {
  max-width: 720px;
  margin: 0 auto;
}

.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.form-group { display: flex; flex-direction: column; gap: var(--space-1); }

.form-group.full-width { grid-column: 1 / -1; }

.form-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.form-label .required {
  color: var(--accent-teal);
  margin-left: 2px;
}

.form-input,
.form-select,
.form-textarea {
  padding: 12px 16px;
  font-size: 0.9375rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  transition: all var(--transition-fast);
}

.form-input::placeholder,
.form-textarea::placeholder { color: var(--text-dim); }

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  outline: none;
  border-color: var(--accent-teal);
  box-shadow: 0 0 0 3px var(--accent-teal-glow);
}

.form-input.error,
.form-select.error,
.form-textarea.error {
  border-color: oklch(55% 0.2 25);
  box-shadow: 0 0 0 3px oklch(55% 0.2 25 / 0.15);
}

.form-error-msg {
  font-size: 0.8125rem;
  color: oklch(60% 0.18 25);
  display: none;
}

.form-input.error + .form-error-msg,
.form-select.error + .form-error-msg,
.form-textarea.error + .form-error-msg { display: block; }

.form-textarea {
  resize: vertical;
  min-height: 100px;
}

.form-submit {
  margin-top: var(--space-5);
}

.form-success {
  display: none;
  text-align: center;
  padding: var(--space-6);
}

.form-success.active { display: block; }

.form-success-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: oklch(72% 0.18 145 / 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-4);
  color: var(--accent-green);
  font-size: 2rem;
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: var(--space-4);
  left: 50%;
  transform: translateX(-50%);
  z-index: 2000;
  width: calc(100% - 32px);
  max-width: 520px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: var(--space-4);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: flex-start;
  gap: var(--space-4);
  animation: slideUp 0.4s var(--ease-out);
}

.cookie-banner.hidden {
  animation: slideDown 0.3s var(--ease-out) forwards;
}

.cookie-text {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.6;
  flex: 1;
}

.cookie-text a {
  color: var(--accent-teal);
  text-decoration: underline;
}

.cookie-actions {
  display: flex;
  gap: var(--space-2);
  flex-shrink: 0;
}

/* --- Footer --- */
.footer {
  background: var(--bg-primary);
  border-top: 1px solid var(--border-light);
  padding: var(--space-7) 0 var(--space-5);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: var(--space-6);
  margin-bottom: var(--space-6);
}

.footer-brand p {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: var(--space-3);
  line-height: 1.6;
}

.footer-col h4 {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-dim);
  margin-bottom: var(--space-3);
}

.footer-col a {
  display: block;
  padding: var(--space-1) 0;
  font-size: 0.875rem;
  color: var(--text-muted);
  transition: color var(--transition-fast);
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border-light);
  padding-top: var(--space-4);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: var(--text-dim);
}

/* --- Platform Ecosystem Diagram --- */
.ecosystem-diagram {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.eco-node {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  text-align: center;
  min-width: 200px;
  max-width: 260px;
  flex: 1;
  transition: all var(--transition-base);
}

.eco-node:hover {
  border-color: var(--accent-teal);
  box-shadow: var(--shadow-glow-teal);
}

.eco-node-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: oklch(68% 0.14 225 / 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-3);
  color: var(--accent-teal);
}

.eco-node h3 {
  font-size: 1.0625rem;
  margin-bottom: var(--space-2);
}

.eco-node p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.eco-connector {
  display: flex;
  align-items: center;
  color: var(--accent-teal);
  font-size: 1.5rem;
  font-weight: 300;
}

.eco-center {
  text-align: center;
  padding: var(--space-4);
}

.eco-center-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 8px 16px;
  background: oklch(68% 0.14 225 / 0.1);
  border: 1px solid oklch(68% 0.14 225 / 0.25);
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--accent-teal);
  letter-spacing: 0.05em;
}

/* --- Featured Product Banner --- */
.featured-banner {
  background: linear-gradient(135deg, var(--bg-secondary), var(--bg-card));
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  flex-wrap: wrap;
}

.featured-banner-content h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-1);
}

.featured-banner-content .tag {
  display: inline-block;
  padding: 3px 10px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent-green);
  background: oklch(72% 0.18 145 / 0.1);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-2);
}

/* --- CTAs / Callouts --- */
.cta-section {
  background: linear-gradient(135deg, var(--bg-secondary), var(--bg-card));
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  text-align: center;
}

.cta-section h2 {
  margin-bottom: var(--space-3);
}

.cta-section p {
  color: var(--text-muted);
  margin-bottom: var(--space-4);
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

/* --- Security Features Grid --- */
.security-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.security-grid .card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.security-grid .card-icon {
  background: oklch(72% 0.18 145 / 0.1);
  color: var(--accent-green);
}

/* --- Benefits with icons --- */
.benefit-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.benefit-item {
  display: flex;
  gap: var(--space-4);
  padding: var(--space-4);
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.benefit-item:hover { border-color: var(--border-default); }

.benefit-icon {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: oklch(68% 0.14 225 / 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-teal);
}

.benefit-text h4 {
  font-size: 1rem;
  margin-bottom: var(--space-1);
}

.benefit-text p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* --- Chevron / Arrow links --- */
.arrow-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--accent-teal);
  transition: gap var(--transition-fast);
}

.arrow-link:hover { gap: var(--space-3); }

/* --- Animations --- */
@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideUp {
  from { opacity: 0; transform: translateX(-50%) translateY(20px); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

@keyframes slideDown {
  from { opacity: 1; transform: translateX(-50%) translateY(0); }
  to { opacity: 0; transform: translateX(-50%) translateY(20px); }
}

@keyframes statSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Scroll reveal */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s var(--ease-out), transform 0.6s var(--ease-out);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* --- Page Header (non-home hero) --- */
.page-hero {
  padding: calc(var(--header-height) + var(--space-7)) 0 var(--space-7);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, var(--accent-teal-glow), transparent 70%);
  pointer-events: none;
}

.page-hero h1 { margin-bottom: var(--space-3); }
.page-hero p {
  font-size: 1.125rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto;
}

/* --- Data Lifecycle Diagram --- */
.lifecycle-diagram {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-3);
}

.lifecycle-row {
  display: flex;
  gap: var(--space-3);
  flex-wrap: wrap;
  justify-content: center;
}

.lifecycle-step {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-3) var(--space-4);
  text-align: center;
  min-width: 120px;
  transition: all var(--transition-base);
}

.lifecycle-step:hover {
  border-color: var(--accent-teal);
  background: var(--bg-elevated);
}

.lifecycle-step-num {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--accent-teal);
  margin-bottom: var(--space-1);
}

.lifecycle-step h4 {
  font-size: 0.9375rem;
}

.lifecycle-arrow-down {
  color: var(--accent-teal);
  font-size: 1.25rem;
}

/* --- Product Table --- */
.product-table {
  width: 100%;
  border-collapse: collapse;
}

.product-table th {
  text-align: left;
  padding: var(--space-3);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-dim);
  border-bottom: 1px solid var(--border-light);
}

.product-table td {
  padding: var(--space-3);
  font-size: 0.9375rem;
  border-bottom: 1px solid var(--border-light);
}

.product-table tbody tr {
  transition: background var(--transition-fast);
}

.product-table tbody tr:hover {
  background: var(--bg-hover);
}

/* --- Icon Badge --- */
.icon-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: oklch(68% 0.14 225 / 0.1);
  color: var(--accent-teal);
}

/* --- Support Grid --- */
.support-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-4);
  text-align: center;
}

.support-card h4 {
  margin: var(--space-3) 0 var(--space-2);
}

.support-card p {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* --- Check List --- */
.check-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-3);
}

.check-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-3);
}

.check-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: oklch(72% 0.18 145 / 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-green);
  font-size: 0.75rem;
  margin-top: 1px;
}

.check-text h4 {
  font-size: 0.9375rem;
  margin-bottom: var(--space-1);
}

.check-text p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* --- Divider --- */
.divider {
  height: 1px;
  background: var(--border-light);
  margin: var(--space-7) 0;
}

/* --- Text Center Utility --- */
.text-center { text-align: center; }

/* --- Responsive --- */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-hamburger { display: flex; }

  .hero-split {
    grid-template-columns: 1fr;
    gap: var(--space-5);
  }

  .card-grid { grid-template-columns: repeat(2, 1fr); }
  .card-grid-4 { grid-template-columns: repeat(2, 1fr); }
  .security-grid { grid-template-columns: repeat(2, 1fr); }
  .benefit-list { grid-template-columns: 1fr; }
  .check-list { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-brand { grid-column: 1 / -1; }

  .stats-row { gap: var(--space-4); }

  .form-grid { grid-template-columns: 1fr; }

  .lifecycle-row {
    flex-direction: column;
    align-items: center;
  }

  .eco-connector {
    transform: rotate(90deg);
  }

  .ecosystem-diagram {
    flex-direction: column;
  }
}

@media (max-width: 640px) {
  :root {
    --header-height: 60px;
  }

  .section { padding: var(--space-6) 0; }
  .hero { padding-top: calc(var(--header-height) + var(--space-5)); }

  .card-grid,
  .card-grid-2,
  .card-grid-4,
  .security-grid { grid-template-columns: 1fr; }

  .btn-group {
    flex-direction: column;
  }

  .btn-group .btn { width: 100%; }

  .tabs { flex-direction: column; border-bottom: none; }
  .tab-btn { border-bottom: none; border-left: 2px solid transparent; border-radius: 0; }
  .tab-btn.active { border-bottom-color: transparent; border-left-color: var(--accent-teal); }

  .tabs-pills {
    justify-content: center;
  }

  .cookie-banner {
    flex-direction: column;
    align-items: stretch;
  }

  .cookie-actions {
    justify-content: flex-end;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: var(--space-4);
  }

  .featured-banner {
    flex-direction: column;
    text-align: center;
  }

  .timeline { padding-left: var(--space-3); }
  .timeline-item { padding-left: var(--space-4); }
  .timeline-dot { left: -17px; }

  .accordion-trigger {
    font-size: 0.9375rem;
    padding: var(--space-3) var(--space-3);
  }

  .accordion-content-inner {
    padding: 0 var(--space-3) var(--space-3);
  }

  .stats-row { gap: var(--space-5); }

  .form-card { padding: var(--space-4); }

  .page-hero { padding-top: calc(var(--header-height) + var(--space-5)); }

  .eco-node { min-width: 100%; }

  .product-table { font-size: 0.8125rem; }
  .product-table th, .product-table td { padding: var(--space-2); }
}

/* ============================================================
   WellStream Platform — Shared Stylesheet
   Design: Professional, modern, dark | Energy Industry SaaS
   ============================================================ */

/* --- Design Tokens --- */
:root {
  /* Backgrounds */
  --bg-deep: oklch(12% 0.015 255);
  --bg-primary: oklch(15% 0.02 255);
  --bg-secondary: oklch(19% 0.025 255);
  --bg-card: oklch(22% 0.025 255);
  --bg-elevated: oklch(26% 0.025 255);
  --bg-hover: oklch(28% 0.025 255);

  /* Text */
  --text-primary: oklch(95% 0.005 255);
  --text-secondary: oklch(75% 0.01 255);
  --text-muted: oklch(58% 0.01 255);
  --text-dim: oklch(45% 0.01 255);

  /* Accents */
  --accent-teal: oklch(68% 0.14 225);
  --accent-teal-glow: oklch(68% 0.14 225 / 0.2);
  --accent-blue: oklch(52% 0.17 252);
  --accent-blue-glow: oklch(52% 0.17 252 / 0.2);
  --accent-green: oklch(72% 0.18 145);
  --accent-green-glow: oklch(72% 0.18 145 / 0.15);
  --accent-amber: oklch(75% 0.15 85);

  /* Borders */
  --border-default: oklch(32% 0.015 255);
  --border-light: oklch(24% 0.015 255);
  --border-glow: oklch(68% 0.14 225 / 0.25);

  /* Typography */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;

  /* Spacing Scale (8px base) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;
  --space-10: 128px;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.35);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.45);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.55);
  --shadow-glow-teal: 0 0 30px oklch(68% 0.14 225 / 0.12);
  --shadow-glow-blue: 0 0 30px oklch(52% 0.17 252 / 0.1);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --transition-fast: 150ms var(--ease-out);
  --transition-base: 250ms var(--ease-out);
  --transition-slow: 400ms var(--ease-out);

  /* Layout */
  --max-width: 1200px;
  --max-width-narrow: 900px;
  --header-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-secondary);
  background: var(--bg-deep);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

body.menu-open { overflow: hidden; }

img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font: inherit; border: none; background: none; color: inherit; }
input, select, textarea { font: inherit; color: inherit; }

/* Focus ring */
:focus-visible {
  outline: 2px solid var(--accent-teal);
  outline-offset: 2px;
}

/* Selection */
::selection {
  background: oklch(68% 0.14 225 / 0.3);
  color: var(--text-primary);
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  color: var(--text-primary);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.125rem; }

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-teal);
  margin-bottom: var(--space-3);
}

.section-title { margin-bottom: var(--space-3); }
.section-description {
  font-size: 1.125rem;
  color: var(--text-muted);
  max-width: 680px;
  margin-bottom: var(--space-6);
}

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.container-narrow {
  max-width: var(--max-width-narrow);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.section {
  padding: var(--space-8) 0;
  position: relative;
}

.section-dark { background: var(--bg-primary); }
.section-darker { background: var(--bg-deep); }

.section-header {
  text-align: center;
  margin-bottom: var(--space-6);
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--header-height);
  background: oklch(12% 0.015 255 / 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-light);
  transition: background var(--transition-base);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.01em;
  flex-shrink: 0;
}

.nav-logo-icon {
  width: 32px;
  height: 32px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.nav-link {
  padding: var(--space-2) var(--space-3);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: color var(--transition-fast), background var(--transition-fast);
  white-space: nowrap;
}

.nav-link:hover { color: var(--text-primary); background: var(--bg-hover); }

/* Dropdown */
.nav-dropdown {
  position: relative;
}

.nav-dropdown-toggle {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-2) var(--space-3);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: color var(--transition-fast), background var(--transition-fast);
}

.nav-dropdown-toggle:hover { color: var(--text-primary); background: var(--bg-hover); }

.nav-dropdown-toggle .chevron {
  width: 14px;
  height: 14px;
  transition: transform var(--transition-fast);
}

.nav-dropdown.open .nav-dropdown-toggle .chevron { transform: rotate(180deg); }
.nav-dropdown.open .nav-dropdown-toggle { color: var(--accent-teal); background: var(--bg-hover); }

.nav-dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  min-width: 220px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: var(--space-2);
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-fast), transform var(--transition-fast), visibility var(--transition-fast);
}

.nav-dropdown.open .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.nav-dropdown-menu a {
  display: block;
  padding: var(--space-2) var(--space-3);
  font-size: 0.875rem;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.nav-dropdown-menu a:hover { color: var(--text-primary); background: var(--bg-hover); }

/* Nav CTA Button */
.nav-cta {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--accent-teal);
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
  box-shadow: 0 0 20px var(--accent-teal-glow);
}

.nav-cta:hover {
  background: oklch(73% 0.14 225);
  box-shadow: 0 0 30px var(--accent-teal-glow);
  transform: translateY(-1px);
}

/* Hamburger */
.nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  z-index: 1001;
}

.nav-hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--text-primary);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.nav-hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.nav-hamburger.active span:nth-child(2) { opacity: 0; }
.nav-hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* Mobile nav */
.nav-mobile {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 999;
  background: var(--bg-deep);
  padding: calc(var(--header-height) + var(--space-4)) var(--space-4) var(--space-4);
  overflow-y: auto;
}

.nav-mobile.active { display: flex; flex-direction: column; gap: var(--space-1); }

.nav-mobile a,
.nav-mobile .nav-mobile-section-title {
  display: block;
  padding: var(--space-3);
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.nav-mobile a:hover { color: var(--text-primary); background: var(--bg-hover); }

.nav-mobile-section-title {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  padding-top: var(--space-4);
}

.nav-mobile .nav-cta {
  margin-top: var(--space-4);
  text-align: center;
  justify-content: center;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: 12px 28px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  line-height: 1.4;
}

.btn-primary {
  background: var(--accent-teal);
  color: var(--bg-deep);
  box-shadow: 0 0 24px var(--accent-teal-glow);
}

.btn-primary:hover {
  background: oklch(73% 0.14 225);
  box-shadow: 0 0 36px var(--accent-teal-glow);
  transform: translateY(-2px);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-default);
}

.btn-secondary:hover {
  border-color: var(--accent-teal);
  color: var(--accent-teal);
}

.btn-lg {
  padding: 16px 36px;
  font-size: 1.0625rem;
}

.btn-sm {
  padding: 8px 18px;
  font-size: 0.8125rem;
}

.btn-group {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
}

/* --- Hero --- */
.hero {
  padding: calc(var(--header-height) + var(--space-8)) 0 var(--space-8);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, var(--accent-teal-glow), transparent 70%);
  pointer-events: none;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -200px;
  left: -100px;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, var(--accent-blue-glow), transparent 70%);
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
}

.hero h1 {
  max-width: 800px;
  margin-bottom: var(--space-4);
}

.hero .hero-subtitle {
  font-size: 1.1875rem;
  color: var(--text-muted);
  max-width: 620px;
  margin-bottom: var(--space-5);
  line-height: 1.7;
}

/* Hero with diagram side-by-side */
.hero-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-7);
  align-items: center;
}

/* --- Cards --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  transition: all var(--transition-base);
}

.card:hover {
  border-color: var(--border-default);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-lg);
  background: oklch(68% 0.14 225 / 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-3);
  color: var(--accent-teal);
}

.card-icon svg {
  width: 24px;
  height: 24px;
}

.card h3, .card h4 {
  margin-bottom: var(--space-2);
}

.card p {
  font-size: 0.9375rem;
  color: var(--text-muted);
  line-height: 1.65;
}

/* Card grid layouts */
.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.card-grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.card-grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
}

/* --- Tabs --- */
.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  margin-bottom: var(--space-5);
  border-bottom: 1px solid var(--border-light);
  padding-bottom: 0;
}

.tabs-center { justify-content: center; }

.tab-btn {
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  border-radius: var(--radius-md) var(--radius-md) 0 0;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  margin-bottom: -1px;
}

.tab-btn:hover { color: var(--text-secondary); }

.tab-btn.active {
  color: var(--accent-teal);
  border-bottom-color: var(--accent-teal);
  background: oklch(68% 0.14 225 / 0.06);
}

.tab-panel { display: none; }
.tab-panel.active { display: block; animation: fadeSlideIn 0.3s var(--ease-out); }

/* Industry tabs variant */
.tabs-pills {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-5);
  border-bottom: none;
}

.tab-pill {
  padding: 8px 18px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-muted);
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.tab-pill:hover { color: var(--text-secondary); border-color: var(--border-default); }

.tab-pill.active {
  color: var(--accent-teal);
  background: oklch(68% 0.14 225 / 0.1);
  border-color: oklch(68% 0.14 225 / 0.3);
}

/* --- Accordion --- */
.accordion { display: flex; flex-direction: column; gap: var(--space-2); }

.accordion-item {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition-fast);
}

.accordion-item.active { border-color: var(--border-default); }

.accordion-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-4) var(--space-5);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text-primary);
  text-align: left;
  transition: color var(--transition-fast);
}

.accordion-trigger:hover { color: var(--accent-teal); }

.accordion-trigger .accordion-icon {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-full);
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-base);
  color: var(--text-muted);
}

.accordion-item.active .accordion-icon {
  background: oklch(68% 0.14 225 / 0.15);
  color: var(--accent-teal);
  transform: rotate(45deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s var(--ease-out);
}

.accordion-content-inner {
  padding: 0 var(--space-5) var(--space-5);
  color: var(--text-muted);
  line-height: 1.7;
}

/* --- Stats Circles --- */
.stats-row {
  display: flex;
  justify-content: center;
  gap: var(--space-7);
  flex-wrap: wrap;
}

.stat-circle {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.stat-circle-outer {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  border: 4px solid var(--border-default);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-3);
  position: relative;
  transition: border-color var(--transition-base);
}

.stat-circle-outer::before {
  content: '';
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 4px solid transparent;
  border-top-color: var(--accent-teal);
  border-right-color: var(--accent-teal);
  animation: statSpin 3s linear infinite;
}

.stat-circle:hover .stat-circle-outer {
  border-color: var(--accent-teal);
}

.stat-value {
  font-size: 2rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.stat-circle .stat-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  max-width: 160px;
  line-height: 1.4;
}

/* --- Timeline --- */
.timeline { position: relative; padding-left: var(--space-5); }

.timeline::before {
  content: '';
  position: absolute;
  left: 16px;
  top: 8px;
  bottom: 8px;
  width: 2px;
  background: var(--border-default);
}

.timeline-item {
  position: relative;
  padding-left: var(--space-5);
  padding-bottom: var(--space-5);
}

.timeline-item:last-child { padding-bottom: 0; }

.timeline-dot {
  position: absolute;
  left: -21px;
  top: 8px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--accent-teal);
  box-shadow: 0 0 12px var(--accent-teal-glow);
}

.timeline-duration {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--accent-teal);
  margin-bottom: var(--space-1);
}

.timeline-desc {
  font-size: 0.9375rem;
  color: var(--text-muted);
  margin-bottom: var(--space-3);
}

.progress-bar {
  height: 6px;
  background: var(--bg-elevated);
  border-radius: var(--radius-full);
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  border-radius: var(--radius-full);
  background: linear-gradient(90deg, var(--accent-teal), var(--accent-blue));
  transition: width 1s var(--ease-out);
}

.progress-25 { width: 25%; }
.progress-50 { width: 50%; }
.progress-100 { width: 100%; }

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s var(--ease-in-out);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 var(--space-1);
}

.testimonial-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.125rem;
  color: var(--text-primary);
  line-height: 1.7;
  font-style: italic;
  margin-bottom: var(--space-4);
}

.testimonial-quote::before { content: '"'; }
.testimonial-quote::after { content: '"'; }

.testimonial-author {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--accent-teal);
}

.testimonial-role {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: var(--space-1);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  margin-top: var(--space-5);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-default);
  transition: all var(--transition-fast);
}

.carousel-dot.active { background: var(--accent-teal); width: 28px; border-radius: var(--radius-full); }
.carousel-dot:hover { background: var(--text-muted); }

/* --- Forms --- */
.form-section {
  max-width: 720px;
  margin: 0 auto;
}

.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.form-group { display: flex; flex-direction: column; gap: var(--space-1); }

.form-group.full-width { grid-column: 1 / -1; }

.form-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.form-label .required {
  color: var(--accent-teal);
  margin-left: 2px;
}

.form-input,
.form-select,
.form-textarea {
  padding: 12px 16px;
  font-size: 0.9375rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  transition: all var(--transition-fast);
}

.form-input::placeholder,
.form-textarea::placeholder { color: var(--text-dim); }

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  outline: none;
  border-color: var(--accent-teal);
  box-shadow: 0 0 0 3px var(--accent-teal-glow);
}

.form-input.error,
.form-select.error,
.form-textarea.error {
  border-color: oklch(55% 0.2 25);
  box-shadow: 0 0 0 3px oklch(55% 0.2 25 / 0.15);
}

.form-error-msg {
  font-size: 0.8125rem;
  color: oklch(60% 0.18 25);
  display: none;
}

.form-input.error + .form-error-msg,
.form-select.error + .form-error-msg,
.form-textarea.error + .form-error-msg { display: block; }

.form-textarea {
  resize: vertical;
  min-height: 100px;
}

.form-submit {
  margin-top: var(--space-5);
}

.form-success {
  display: none;
  text-align: center;
  padding: var(--space-6);
}

.form-success.active { display: block; }

.form-success-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: oklch(72% 0.18 145 / 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-4);
  color: var(--accent-green);
  font-size: 2rem;
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: var(--space-4);
  left: 50%;
  transform: translateX(-50%);
  z-index: 2000;
  width: calc(100% - 32px);
  max-width: 520px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: var(--space-4);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: flex-start;
  gap: var(--space-4);
  animation: slideUp 0.4s var(--ease-out);
}

.cookie-banner.hidden {
  animation: slideDown 0.3s var(--ease-out) forwards;
}

.cookie-text {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.6;
  flex: 1;
}

.cookie-text a {
  color: var(--accent-teal);
  text-decoration: underline;
}

.cookie-actions {
  display: flex;
  gap: var(--space-2);
  flex-shrink: 0;
}

/* --- Footer --- */
.footer {
  background: var(--bg-primary);
  border-top: 1px solid var(--border-light);
  padding: var(--space-7) 0 var(--space-5);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: var(--space-6);
  margin-bottom: var(--space-6);
}

.footer-brand p {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: var(--space-3);
  line-height: 1.6;
}

.footer-col h4 {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-dim);
  margin-bottom: var(--space-3);
}

.footer-col a {
  display: block;
  padding: var(--space-1) 0;
  font-size: 0.875rem;
  color: var(--text-muted);
  transition: color var(--transition-fast);
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border-light);
  padding-top: var(--space-4);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: var(--text-dim);
}

/* --- Platform Ecosystem Diagram --- */
.ecosystem-diagram {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.eco-node {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  text-align: center;
  min-width: 200px;
  max-width: 260px;
  flex: 1;
  transition: all var(--transition-base);
}

.eco-node:hover {
  border-color: var(--accent-teal);
  box-shadow: var(--shadow-glow-teal);
}

.eco-node-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: oklch(68% 0.14 225 / 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-3);
  color: var(--accent-teal);
}

.eco-node h3 {
  font-size: 1.0625rem;
  margin-bottom: var(--space-2);
}

.eco-node p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.eco-connector {
  display: flex;
  align-items: center;
  color: var(--accent-teal);
  font-size: 1.5rem;
  font-weight: 300;
}

.eco-center {
  text-align: center;
  padding: var(--space-4);
}

.eco-center-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 8px 16px;
  background: oklch(68% 0.14 225 / 0.1);
  border: 1px solid oklch(68% 0.14 225 / 0.25);
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--accent-teal);
  letter-spacing: 0.05em;
}

/* --- Featured Product Banner --- */
.featured-banner {
  background: linear-gradient(135deg, var(--bg-secondary), var(--bg-card));
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  flex-wrap: wrap;
}

.featured-banner-content h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-1);
}

.featured-banner-content .tag {
  display: inline-block;
  padding: 3px 10px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent-green);
  background: oklch(72% 0.18 145 / 0.1);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-2);
}

/* --- CTAs / Callouts --- */
.cta-section {
  background: linear-gradient(135deg, var(--bg-secondary), var(--bg-card));
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  text-align: center;
}

.cta-section h2 {
  margin-bottom: var(--space-3);
}

.cta-section p {
  color: var(--text-muted);
  margin-bottom: var(--space-4);
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

/* --- Security Features Grid --- */
.security-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.security-grid .card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.security-grid .card-icon {
  background: oklch(72% 0.18 145 / 0.1);
  color: var(--accent-green);
}

/* --- Benefits with icons --- */
.benefit-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.benefit-item {
  display: flex;
  gap: var(--space-4);
  padding: var(--space-4);
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.benefit-item:hover { border-color: var(--border-default); }

.benefit-icon {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: oklch(68% 0.14 225 / 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-teal);
}

.benefit-text h4 {
  font-size: 1rem;
  margin-bottom: var(--space-1);
}

.benefit-text p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* --- Chevron / Arrow links --- */
.arrow-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--accent-teal);
  transition: gap var(--transition-fast);
}

.arrow-link:hover { gap: var(--space-3); }

/* --- Animations --- */
@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideUp {
  from { opacity: 0; transform: translateX(-50%) translateY(20px); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

@keyframes slideDown {
  from { opacity: 1; transform: translateX(-50%) translateY(0); }
  to { opacity: 0; transform: translateX(-50%) translateY(20px); }
}

@keyframes statSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Scroll reveal */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s var(--ease-out), transform 0.6s var(--ease-out);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* --- Page Header (non-home hero) --- */
.page-hero {
  padding: calc(var(--header-height) + var(--space-7)) 0 var(--space-7);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, var(--accent-teal-glow), transparent 70%);
  pointer-events: none;
}

.page-hero h1 { margin-bottom: var(--space-3); }
.page-hero p {
  font-size: 1.125rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto;
}

/* --- Data Lifecycle Diagram --- */
.lifecycle-diagram {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-3);
}

.lifecycle-row {
  display: flex;
  gap: var(--space-3);
  flex-wrap: wrap;
  justify-content: center;
}

.lifecycle-step {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-3) var(--space-4);
  text-align: center;
  min-width: 120px;
  transition: all var(--transition-base);
}

.lifecycle-step:hover {
  border-color: var(--accent-teal);
  background: var(--bg-elevated);
}

.lifecycle-step-num {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--accent-teal);
  margin-bottom: var(--space-1);
}

.lifecycle-step h4 {
  font-size: 0.9375rem;
}

.lifecycle-arrow-down {
  color: var(--accent-teal);
  font-size: 1.25rem;
}

/* --- Product Table --- */
.product-table {
  width: 100%;
  border-collapse: collapse;
}

.product-table th {
  text-align: left;
  padding: var(--space-3);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-dim);
  border-bottom: 1px solid var(--border-light);
}

.product-table td {
  padding: var(--space-3);
  font-size: 0.9375rem;
  border-bottom: 1px solid var(--border-light);
}

.product-table tbody tr {
  transition: background var(--transition-fast);
}

.product-table tbody tr:hover {
  background: var(--bg-hover);
}

/* --- Icon Badge --- */
.icon-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: oklch(68% 0.14 225 / 0.1);
  color: var(--accent-teal);
}

/* --- Support Grid --- */
.support-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-4);
  text-align: center;
}

.support-card h4 {
  margin: var(--space-3) 0 var(--space-2);
}

.support-card p {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* --- Check List --- */
.check-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-3);
}

.check-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-3);
}

.check-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: oklch(72% 0.18 145 / 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-green);
  font-size: 0.75rem;
  margin-top: 1px;
}

.check-text h4 {
  font-size: 0.9375rem;
  margin-bottom: var(--space-1);
}

.check-text p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* --- Divider --- */
.divider {
  height: 1px;
  background: var(--border-light);
  margin: var(--space-7) 0;
}

/* --- Text Center Utility --- */
.text-center { text-align: center; }

/* --- Responsive --- */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-hamburger { display: flex; }

  .hero-split {
    grid-template-columns: 1fr;
    gap: var(--space-5);
  }

  .card-grid { grid-template-columns: repeat(2, 1fr); }
  .card-grid-4 { grid-template-columns: repeat(2, 1fr); }
  .security-grid { grid-template-columns: repeat(2, 1fr); }
  .benefit-list { grid-template-columns: 1fr; }
  .check-list { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-brand { grid-column: 1 / -1; }

  .stats-row { gap: var(--space-4); }

  .form-grid { grid-template-columns: 1fr; }

  .lifecycle-row {
    flex-direction: column;
    align-items: center;
  }

  .eco-connector {
    transform: rotate(90deg);
  }

  .ecosystem-diagram {
    flex-direction: column;
  }
}

@media (max-width: 640px) {
  :root {
    --header-height: 60px;
  }

  .section { padding: var(--space-6) 0; }
  .hero { padding-top: calc(var(--header-height) + var(--space-5)); }

  .card-grid,
  .card-grid-2,
  .card-grid-4,
  .security-grid { grid-template-columns: 1fr; }

  .btn-group {
    flex-direction: column;
  }

  .btn-group .btn { width: 100%; }

  .tabs { flex-direction: column; border-bottom: none; }
  .tab-btn { border-bottom: none; border-left: 2px solid transparent; border-radius: 0; }
  .tab-btn.active { border-bottom-color: transparent; border-left-color: var(--accent-teal); }

  .tabs-pills {
    justify-content: center;
  }

  .cookie-banner {
    flex-direction: column;
    align-items: stretch;
  }

  .cookie-actions {
    justify-content: flex-end;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: var(--space-4);
  }

  .featured-banner {
    flex-direction: column;
    text-align: center;
  }

  .timeline { padding-left: var(--space-3); }
  .timeline-item { padding-left: var(--space-4); }
  .timeline-dot { left: -17px; }

  .accordion-trigger {
    font-size: 0.9375rem;
    padding: var(--space-3) var(--space-3);
  }

  .accordion-content-inner {
    padding: 0 var(--space-3) var(--space-3);
  }

  .stats-row { gap: var(--space-5); }

  .form-card { padding: var(--space-4); }

  .page-hero { padding-top: calc(var(--header-height) + var(--space-5)); }

  .eco-node { min-width: 100%; }

  .product-table { font-size: 0.8125rem; }
  .product-table th, .product-table td { padding: var(--space-2); }
}

raw_arguments.content:
/* ============================================================
   WellStream Platform — Shared Stylesheet
   Design: Professional, modern, dark | Energy Industry SaaS
   ============================================================ */

/* --- Design Tokens --- */
:root {
  /* Backgrounds */
  --bg-deep: oklch(12% 0.015 255);
  --bg-primary: oklch(15% 0.02 255);
  --bg-secondary: oklch(19% 0.025 255);
  --bg-card: oklch(22% 0.025 255);
  --bg-elevated: oklch(26% 0.025 255);
  --bg-hover: oklch(28% 0.025 255);

  /* Text */
  --text-primary: oklch(95% 0.005 255);
  --text-secondary: oklch(75% 0.01 255);
  --text-muted: oklch(58% 0.01 255);
  --text-dim: oklch(45% 0.01 255);

  /* Accents */
  --accent-teal: oklch(68% 0.14 225);
  --accent-teal-glow: oklch(68% 0.14 225 / 0.2);
  --accent-blue: oklch(52% 0.17 252);
  --accent-blue-glow: oklch(52% 0.17 252 / 0.2);
  --accent-green: oklch(72% 0.18 145);
  --accent-green-glow: oklch(72% 0.18 145 / 0.15);
  --accent-amber: oklch(75% 0.15 85);

  /* Borders */
  --border-default: oklch(32% 0.015 255);
  --border-light: oklch(24% 0.015 255);
  --border-glow: oklch(68% 0.14 225 / 0.25);

  /* Typography */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;

  /* Spacing Scale (8px base) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;
  --space-10: 128px;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.35);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.45);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.55);
  --shadow-glow-teal: 0 0 30px oklch(68% 0.14 225 / 0.12);
  --shadow-glow-blue: 0 0 30px oklch(52% 0.17 252 / 0.1);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --transition-fast: 150ms var(--ease-out);
  --transition-base: 250ms var(--ease-out);
  --transition-slow: 400ms var(--ease-out);

  /* Layout */
  --max-width: 1200px;
  --max-width-narrow: 900px;
  --header-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-secondary);
  background: var(--bg-deep);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

body.menu-open { overflow: hidden; }

img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font: inherit; border: none; background: none; color: inherit; }
input, select, textarea { font: inherit; color: inherit; }

/* Focus ring */
:focus-visible {
  outline: 2px solid var(--accent-teal);
  outline-offset: 2px;
}

/* Selection */
::selection {
  background: oklch(68% 0.14 225 / 0.3);
  color: var(--text-primary);
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  color: var(--text-primary);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.125rem; }

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-teal);
  margin-bottom: var(--space-3);
}

.section-title { margin-bottom: var(--space-3); }
.section-description {
  font-size: 1.125rem;
  color: var(--text-muted);
  max-width: 680px;
  margin-bottom: var(--space-6);
}

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.container-narrow {
  max-width: var(--max-width-narrow);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.section {
  padding: var(--space-8) 0;
  position: relative;
}

.section-dark { background: var(--bg-primary); }
.section-darker { background: var(--bg-deep); }

.section-header {
  text-align: center;
  margin-bottom: var(--space-6);
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--header-height);
  background: oklch(12% 0.015 255 / 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-light);
  transition: background var(--transition-base);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.01em;
  flex-shrink: 0;
}

.nav-logo-icon {
  width: 32px;
  height: 32px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.nav-link {
  padding: var(--space-2) var(--space-3);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: color var(--transition-fast), background var(--transition-fast);
  white-space: nowrap;
}

.nav-link:hover { color: var(--text-primary); background: var(--bg-hover); }

/* Dropdown */
.nav-dropdown {
  position: relative;
}

.nav-dropdown-toggle {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-2) var(--space-3);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: color var(--transition-fast), background var(--transition-fast);
}

.nav-dropdown-toggle:hover { color: var(--text-primary); background: var(--bg-hover); }

.nav-dropdown-toggle .chevron {
  width: 14px;
  height: 14px;
  transition: transform var(--transition-fast);
}

.nav-dropdown.open .nav-dropdown-toggle .chevron { transform: rotate(180deg); }
.nav-dropdown.open .nav-dropdown-toggle { color: var(--accent-teal); background: var(--bg-hover); }

.nav-dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  min-width: 220px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: var(--space-2);
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-fast), transform var(--transition-fast), visibility var(--transition-fast);
}

.nav-dropdown.open .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.nav-dropdown-menu a {
  display: block;
  padding: var(--space-2) var(--space-3);
  font-size: 0.875rem;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.nav-dropdown-menu a:hover { color: var(--text-primary); background: var(--bg-hover); }

/* Nav CTA Button */
.nav-cta {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--accent-teal);
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
  box-shadow: 0 0 20px var(--accent-teal-glow);
}

.nav-cta:hover {
  background: oklch(73% 0.14 225);
  box-shadow: 0 0 30px var(--accent-teal-glow);
  transform: translateY(-1px);
}

/* Hamburger */
.nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  z-index: 1001;
}

.nav-hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--text-primary);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.nav-hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.nav-hamburger.active span:nth-child(2) { opacity: 0; }
.nav-hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* Mobile nav */
.nav-mobile {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 999;
  background: var(--bg-deep);
  padding: calc(var(--header-height) + var(--space-4)) var(--space-4) var(--space-4);
  overflow-y: auto;
}

.nav-mobile.active { display: flex; flex-direction: column; gap: var(--space-1); }

.nav-mobile a,
.nav-mobile .nav-mobile-section-title {
  display: block;
  padding: var(--space-3);
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.nav-mobile a:hover { color: var(--text-primary); background: var(--bg-hover); }

.nav-mobile-section-title {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  padding-top: var(--space-4);
}

.nav-mobile .nav-cta {
  margin-top: var(--space-4);
  text-align: center;
  justify-content: center;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: 12px 28px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  line-height: 1.4;
}

.btn-primary {
  background: var(--accent-teal);
  color: var(--bg-deep);
  box-shadow: 0 0 24px var(--accent-teal-glow);
}

.btn-primary:hover {
  background: oklch(73% 0.14 225);
  box-shadow: 0 0 36px var(--accent-teal-glow);
  transform: translateY(-2px);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-default);
}

.btn-secondary:hover {
  border-color: var(--accent-teal);
  color: var(--accent-teal);
}

.btn-lg {
  padding: 16px 36px;
  font-size: 1.0625rem;
}

.btn-sm {
  padding: 8px 18px;
  font-size: 0.8125rem;
}

.btn-group {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
}

/* --- Hero --- */
.hero {
  padding: calc(var(--header-height) + var(--space-8)) 0 var(--space-8);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, var(--accent-teal-glow), transparent 70%);
  pointer-events: none;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -200px;
  left: -100px;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, var(--accent-blue-glow), transparent 70%);
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
}

.hero h1 {
  max-width: 800px;
  margin-bottom: var(--space-4);
}

.hero .hero-subtitle {
  font-size: 1.1875rem;
  color: var(--text-muted);
  max-width: 620px;
  margin-bottom: var(--space-5);
  line-height: 1.7;
}

/* Hero with diagram side-by-side */
.hero-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-7);
  align-items: center;
}

/* --- Cards --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  transition: all var(--transition-base);
}

.card:hover {
  border-color: var(--border-default);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-lg);
  background: oklch(68% 0.14 225 / 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-3);
  color: var(--accent-teal);
}

.card-icon svg {
  width: 24px;
  height: 24px;
}

.card h3, .card h4 {
  margin-bottom: var(--space-2);
}

.card p {
  font-size: 0.9375rem;
  color: var(--text-muted);
  line-height: 1.65;
}

/* Card grid layouts */
.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.card-grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.card-grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
}

/* --- Tabs --- */
.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  margin-bottom: var(--space-5);
  border-bottom: 1px solid var(--border-light);
  padding-bottom: 0;
}

.tabs-center { justify-content: center; }

.tab-btn {
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  border-radius: var(--radius-md) var(--radius-md) 0 0;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  margin-bottom: -1px;
}

.tab-btn:hover { color: var(--text-secondary); }

.tab-btn.active {
  color: var(--accent-teal);
  border-bottom-color: var(--accent-teal);
  background: oklch(68% 0.14 225 / 0.06);
}

.tab-panel { display: none; }
.tab-panel.active { display: block; animation: fadeSlideIn 0.3s var(--ease-out); }

/* Industry tabs variant */
.tabs-pills {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-5);
  border-bottom: none;
}

.tab-pill {
  padding: 8px 18px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-muted);
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.tab-pill:hover { color: var(--text-secondary); border-color: var(--border-default); }

.tab-pill.active {
  color: var(--accent-teal);
  background: oklch(68% 0.14 225 / 0.1);
  border-color: oklch(68% 0.14 225 / 0.3);
}

/* --- Accordion --- */
.accordion { display: flex; flex-direction: column; gap: var(--space-2); }

.accordion-item {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition-fast);
}

.accordion-item.active { border-color: var(--border-default); }

.accordion-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-4) var(--space-5);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text-primary);
  text-align: left;
  transition: color var(--transition-fast);
}

.accordion-trigger:hover { color: var(--accent-teal); }

.accordion-trigger .accordion-icon {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-full);
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-base);
  color: var(--text-muted);
}

.accordion-item.active .accordion-icon {
  background: oklch(68% 0.14 225 / 0.15);
  color: var(--accent-teal);
  transform: rotate(45deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s var(--ease-out);
}

.accordion-content-inner {
  padding: 0 var(--space-5) var(--space-5);
  color: var(--text-muted);
  line-height: 1.7;
}

/* --- Stats Circles --- */
.stats-row {
  display: flex;
  justify-content: center;
  gap: var(--space-7);
  flex-wrap: wrap;
}

.stat-circle {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.stat-circle-outer {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  border: 4px solid var(--border-default);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-3);
  position: relative;
  transition: border-color var(--transition-base);
}

.stat-circle-outer::before {
  content: '';
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 4px solid transparent;
  border-top-color: var(--accent-teal);
  border-right-color: var(--accent-teal);
  animation: statSpin 3s linear infinite;
}

.stat-circle:hover .stat-circle-outer {
  border-color: var(--accent-teal);
}

.stat-value {
  font-size: 2rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.stat-circle .stat-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  max-width: 160px;
  line-height: 1.4;
}

/* --- Timeline --- */
.timeline { position: relative; padding-left: var(--space-5); }

.timeline::before {
  content: '';
  position: absolute;
  left: 16px;
  top: 8px;
  bottom: 8px;
  width: 2px;
  background: var(--border-default);
}

.timeline-item {
  position: relative;
  padding-left: var(--space-5);
  padding-bottom: var(--space-5);
}

.timeline-item:last-child { padding-bottom: 0; }

.timeline-dot {
  position: absolute;
  left: -21px;
  top: 8px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--accent-teal);
  box-shadow: 0 0 12px var(--accent-teal-glow);
}

.timeline-duration {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--accent-teal);
  margin-bottom: var(--space-1);
}

.timeline-desc {
  font-size: 0.9375rem;
  color: var(--text-muted);
  margin-bottom: var(--space-3);
}

.progress-bar {
  height: 6px;
  background: var(--bg-elevated);
  border-radius: var(--radius-full);
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  border-radius: var(--radius-full);
  background: linear-gradient(90deg, var(--accent-teal), var(--accent-blue));
  transition: width 1s var(--ease-out);
}

.progress-25 { width: 25%; }
.progress-50 { width: 50%; }
.progress-100 { width: 100%; }

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s var(--ease-in-out);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 var(--space-1);
}

.testimonial-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.125rem;
  color: var(--text-primary);
  line-height: 1.7;
  font-style: italic;
  margin-bottom: var(--space-4);
}

.testimonial-quote::before { content: '"'; }
.testimonial-quote::after { content: '"'; }

.testimonial-author {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--accent-teal);
}

.testimonial-role {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: var(--space-1);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  margin-top: var(--space-5);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-default);
  transition: all var(--transition-fast);
}

.carousel-dot.active { background: var(--accent-teal); width: 28px; border-radius: var(--radius-full); }
.carousel-dot:hover { background: var(--text-muted); }

/* --- Forms --- */
.form-section {
  max-width: 720px;
  margin: 0 auto;
}

.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.form-group { display: flex; flex-direction: column; gap: var(--space-1); }

.form-group.full-width { grid-column: 1 / -1; }

.form-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.form-label .required {
  color: var(--accent-teal);
  margin-left: 2px;
}

.form-input,
.form-select,
.form-textarea {
  padding: 12px 16px;
  font-size: 0.9375rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  transition: all var(--transition-fast);
}

.form-input::placeholder,
.form-textarea::placeholder { color: var(--text-dim); }

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  outline: none;
  border-color: var(--accent-teal);
  box-shadow: 0 0 0 3px var(--accent-teal-glow);
}

.form-input.error,
.form-select.error,
.form-textarea.error {
  border-color: oklch(55% 0.2 25);
  box-shadow: 0 0 0 3px oklch(55% 0.2 25 / 0.15);
}

.form-error-msg {
  font-size: 0.8125rem;
  color: oklch(60% 0.18 25);
  display: none;
}

.form-input.error + .form-error-msg,
.form-select.error + .form-error-msg,
.form-textarea.error + .form-error-msg { display: block; }

.form-textarea {
  resize: vertical;
  min-height: 100px;
}

.form-submit {
  margin-top: var(--space-5);
}

.form-success {
  display: none;
  text-align: center;
  padding: var(--space-6);
}

.form-success.active { display: block; }

.form-success-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: oklch(72% 0.18 145 / 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-4);
  color: var(--accent-green);
  font-size: 2rem;
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: var(--space-4);
  left: 50%;
  transform: translateX(-50%);
  z-index: 2000;
  width: calc(100% - 32px);
  max-width: 520px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: var(--space-4);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: flex-start;
  gap: var(--space-4);
  animation: slideUp 0.4s var(--ease-out);
}

.cookie-banner.hidden {
  animation: slideDown 0.3s var(--ease-out) forwards;
}

.cookie-text {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.6;
  flex: 1;
}

.cookie-text a {
  color: var(--accent-teal);
  text-decoration: underline;
}

.cookie-actions {
  display: flex;
  gap: var(--space-2);
  flex-shrink: 0;
}

/* --- Footer --- */
.footer {
  background: var(--bg-primary);
  border-top: 1px solid var(--border-light);
  padding: var(--space-7) 0 var(--space-5);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: var(--space-6);
  margin-bottom: var(--space-6);
}

.footer-brand p {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: var(--space-3);
  line-height: 1.6;
}

.footer-col h4 {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-dim);
  margin-bottom: var(--space-3);
}

.footer-col a {
  display: block;
  padding: var(--space-1) 0;
  font-size: 0.875rem;
  color: var(--text-muted);
  transition: color var(--transition-fast);
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border-light);
  padding-top: var(--space-4);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: var(--text-dim);
}

/* --- Platform Ecosystem Diagram --- */
.ecosystem-diagram {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.eco-node {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  text-align: center;
  min-width: 200px;
  max-width: 260px;
  flex: 1;
  transition: all var(--transition-base);
}

.eco-node:hover {
  border-color: var(--accent-teal);
  box-shadow: var(--shadow-glow-teal);
}

.eco-node-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: oklch(68% 0.14 225 / 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-3);
  color: var(--accent-teal);
}

.eco-node h3 {
  font-size: 1.0625rem;
  margin-bottom: var(--space-2);
}

.eco-node p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.eco-connector {
  display: flex;
  align-items: center;
  color: var(--accent-teal);
  font-size: 1.5rem;
  font-weight: 300;
}

.eco-center {
  text-align: center;
  padding: var(--space-4);
}

.eco-center-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 8px 16px;
  background: oklch(68% 0.14 225 / 0.1);
  border: 1px solid oklch(68% 0.14 225 / 0.25);
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--accent-teal);
  letter-spacing: 0.05em;
}

/* --- Featured Product Banner --- */
.featured-banner {
  background: linear-gradient(135deg, var(--bg-secondary), var(--bg-card));
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: var(--space-5);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  flex-wrap: wrap;
}

.featured-banner-content h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-1);
}

.featured-banner-content .tag {
  display: inline-block;
  padding: 3px 10px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent-green);
  background: oklch(72% 0.18 145 / 0.1);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-2);
}

/* --- CTAs / Callouts --- */
.cta-section {
  background: linear-gradient(135deg, var(--bg-secondary), var(--bg-card));
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  text-align: center;
}

.cta-section h2 {
  margin-bottom: var(--space-3);
}

.cta-section p {
  color: var(--text-muted);
  margin-bottom: var(--space-4);
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

/* --- Security Features Grid --- */
.security-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.security-grid .card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.security-grid .card-icon {
  background: oklch(72% 0.18 145 / 0.1);
  color: var(--accent-green);
}

/* --- Benefits with icons --- */
.benefit-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.benefit-item {
  display: flex;
  gap: var(--space-4);
  padding: var(--space-4);
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.benefit-item:hover { border-color: var(--border-default); }

.benefit-icon {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: oklch(68% 0.14 225 / 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-teal);
}

.benefit-text h4 {
  font-size: 1rem;
  margin-bottom: var(--space-1);
}

.benefit-text p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* --- Chevron / Arrow links --- */
.arrow-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--accent-teal);
  transition: gap var(--transition-fast);
}

.arrow-link:hover { gap: var(--space-3); }

/* --- Animations --- */
@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideUp {
  from { opacity: 0; transform: translateX(-50%) translateY(20px); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

@keyframes slideDown {
  from { opacity: 1; transform: translateX(-50%) translateY(0); }
  to { opacity: 0; transform: translateX(-50%) translateY(20px); }
}

@keyframes statSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Scroll reveal */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s var(--ease-out), transform 0.6s var(--ease-out);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* --- Page Header (non-home hero) --- */
.page-hero {
  padding: calc(var(--header-height) + var(--space-7)) 0 var(--space-7);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, var(--accent-teal-glow), transparent 70%);
  pointer-events: none;
}

.page-hero h1 { margin-bottom: var(--space-3); }
.page-hero p {
  font-size: 1.125rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto;
}

/* --- Data Lifecycle Diagram --- */
.lifecycle-diagram {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-3);
}

.lifecycle-row {
  display: flex;
  gap: var(--space-3);
  flex-wrap: wrap;
  justify-content: center;
}

.lifecycle-step {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-3) var(--space-4);
  text-align: center;
  min-width: 120px;
  transition: all var(--transition-base);
}

.lifecycle-step:hover {
  border-color: var(--accent-teal);
  background: var(--bg-elevated);
}

.lifecycle-step-num {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--accent-teal);
  margin-bottom: var(--space-1);
}

.lifecycle-step h4 {
  font-size: 0.9375rem;
}

.lifecycle-arrow-down {
  color: var(--accent-teal);
  font-size: 1.25rem;
}

/* --- Product Table --- */
.product-table {
  width: 100%;
  border-collapse: collapse;
}

.product-table th {
  text-align: left;
  padding: var(--space-3);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-dim);
  border-bottom: 1px solid var(--border-light);
}

.product-table td {
  padding: var(--space-3);
  font-size: 0.9375rem;
  border-bottom: 1px solid var(--border-light);
}

.product-table tbody tr {
  transition: background var(--transition-fast);
}

.product-table tbody tr:hover {
  background: var(--bg-hover);
}

/* --- Icon Badge --- */
.icon-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: oklch(68% 0.14 225 / 0.1);
  color: var(--accent-teal);
}

/* --- Support Grid --- */
.support-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-4);
  text-align: center;
}

.support-card h4 {
  margin: var(--space-3) 0 var(--space-2);
}

.support-card p {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* --- Check List --- */
.check-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-3);
}

.check-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-3);
}

.check-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: oklch(72% 0.18 145 / 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-green);
  font-size: 0.75rem;
  margin-top: 1px;
}

.check-text h4 {
  font-size: 0.9375rem;
  margin-bottom: var(--space-1);
}

.check-text p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* --- Divider --- */
.divider {
  height: 1px;
  background: var(--border-light);
  margin: var(--space-7) 0;
}

/* --- Text Center Utility --- */
.text-center { text-align: center; }

/* --- Responsive --- */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-hamburger { display: flex; }

  .hero-split {
    grid-template-columns: 1fr;
    gap: var(--space-5);
  }

  .card-grid { grid-template-columns: repeat(2, 1fr); }
  .card-grid-4 { grid-template-columns: repeat(2, 1fr); }
  .security-grid { grid-template-columns: repeat(2, 1fr); }
  .benefit-list { grid-template-columns: 1fr; }
  .check-list { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-brand { grid-column: 1 / -1; }

  .stats-row { gap: var(--space-4); }

  .form-grid { grid-template-columns: 1fr; }

  .lifecycle-row {
    flex-direction: column;
    align-items: center;
  }

  .eco-connector {
    transform: rotate(90deg);
  }

  .ecosystem-diagram {
    flex-direction: column;
  }
}

@media (max-width: 640px) {
  :root {
    --header-height: 60px;
  }

  .section { padding: var(--space-6) 0; }
  .hero { padding-top: calc(var(--header-height) + var(--space-5)); }

  .card-grid,
  .card-grid-2,
  .card-grid-4,
  .security-grid { grid-template-columns: 1fr; }

  .btn-group {
    flex-direction: column;
  }

  .btn-group .btn { width: 100%; }

  .tabs { flex-direction: column; border-bottom: none; }
  .tab-btn { border-bottom: none; border-left: 2px solid transparent; border-radius: 0; }
  .tab-btn.active { border-bottom-color: transparent; border-left-color: var(--accent-teal); }

  .tabs-pills {
    justify-content: center;
  }

  .cookie-banner {
    flex-direction: column;
    align-items: stretch;
  }

  .cookie-actions {
    justify-content: flex-end;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: var(--space-4);
  }

  .featured-banner {
    flex-direction: column;
    text-align: center;
  }

  .timeline { padding-left: var(--space-3); }
  .timeline-item { padding-left: var(--space-4); }
  .timeline-dot { left: -17px; }

  .accordion-trigger {
    font-size: 0.9375rem;
    padding: var(--space-3) var(--space-3);
  }

  .accordion-content-inner {
    padding: 0 var(--space-3) var(--space-3);
  }

  .stats-row { gap: var(--space-5); }

  .form-card { padding: var(--space-4); }

  .page-hero { padding-top: calc(var(--header-height) + var(--space-5)); }

  .eco-node { min-width: 100%; }

  .product-table { font-size: 0.8125rem; }
  .product-table th, .product-table td { padding: var(--space-2); }
}

