      touchEndX = e.changedTouches[0].screenX;
      const diff = touchStartX - touchEndX;
      if (Math.abs(diff) > 50) {
        if (diff > 0 && currentIndex < slides.length - 1) {
          goTo(currentIndex + 1);
        } else if (diff < 0 && currentIndex > 0) {
          goTo(currentIndex - 1);
        }
        resetAutoPlay();
      }
    });
  });

